import { useState } from 'react';

export default function {{component_name}}({ source }: { source: string[] }) {
  const [q, setQ] = useState('');
  const matches = q ? source.filter((s) => s.toLowerCase().includes(q.toLowerCase())).slice(0, 5) : [];

  return (
    <div className="relative">
      <input value={q} onChange={(e) => setQ(e.target.value)} className="border rounded px-3 py-2 w-full" />
      {matches.length > 0 && (
        <ul className="absolute bg-white border rounded w-full mt-1 shadow">
          {matches.map((m) => (
            <li key={m} className="px-3 py-1 hover:bg-gray-100 cursor-pointer" onClick={() => setQ(m)}>{m}</li>
          ))}
        </ul>
      )}
    </div>
  );
}
